sql.where:
su.deleted = 0



    AND su.user_id = #{reqVO.userId}


    AND su.user_name LIKE CONCAT('%', #{reqVO.userName}, '%')


    AND su.user_phone = #{reqVO.userPhone}


    AND su.dept_id = #{reqVO.deptId}


    AND su.role_id = #{reqVO.roleId}


    AND su.status_id = #{reqVO.statusId}


    AND su.create_by = #{reqVO.createBy}


    AND su.update_by = #{reqVO.updateBy}


    AND su.skill_tags LIKE CONCAT('%', #{reqVO.skillTags}, '%')


    AND su.work_trajectory_id = #{reqVO.workTrajectoryId}


    AND su.team_id = #{reqVO.teamId}


    AND su.area_code = #{reqVO.areaCode}


    AND su.job_type_id = #{reqVO.jobTypeId}


    AND su.person_status_id = #{reqVO.personStatusId}


    AND su.phone = #{reqVO.phone}




    AND su.entry_time BETWEEN #{reqVO.entryTime[0]} AND #{reqVO.entryTime[1]}




    AND su.total_attendance_days = #{reqVO.totalAttendanceDays}


    AND su.average_score = #{reqVO.averageScore}



    AND su.last_work_trace LIKE CONCAT('%', #{reqVO.lastWorkTrace}, '%')




    AND su.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
